                    serde_json::json!([]),
                    serde_json::json!([]),
                ),
                LogEntry::llm_response(
                    now,
                    1,
                    Some("msg_1".into()),
                    None,
                    None,
                    Some(vec![ToolCallData {
                        id: "call_abc".into(),
                        name: "echo".into(),
                        arguments: serde_json::json!({"text": "hello"}),
                    }]),
                    UsageData {
                        input_tokens: 10,
                        output_tokens: 5,
                    },
                ),
                LogEntry::tool_execution(
                    now,
                    1,
                    "call_abc".into(),
                    "call_abc".into(),
                    "echo".into(),
                    serde_json::json!({"text": "hello"}),
                    "hello".into(),
                ),
                LogEntry::llm_prompt(
                    now,
                    1,
                    "d".into(),
                    "m".into(),
                    serde_json::json!([]),
