            .expect("create");
        let now = Utc::now();

        write_log(
            session,
            &[
                LogEntry::user_input(now, 1, "echo hello".into()),
                LogEntry::llm_prompt(
                    now,
                    1,
                    "d".into(),
                    "m".into(),
                    serde_json::json!([]),
                    serde_json::json!([]),
                ),
                LogEntry::llm_response(
                    now,
                    1,
                    Some("msg_1".into()),
                    None,
                    None,
                    Some(vec![ToolCallData {
                        id: "call_abc".into(),
